# frozen_string_literal: true

require 'spec_helper'
require 'tmpdir'

# rubocop:disable Metrics/BlockLength
RSpec.describe Mxrb::RubyApp::ProjectJavaScriptActions do
  def action_source(name, parameters = '', imports: '')
    <<~JS
      // This file was generated by Mendix Studio Pro.
      import { Big } from "big.js";
      import "mx-global";
      #{imports}
      /**
       * @param {MxObject} item - The item.
       * @param {Big} amount - The amount.
       * @returns {Promise.<boolean>}
       */
      export async function #{name}(#{parameters}) {
      \t// BEGIN USER CODE
      \treturn true;
      \t// END USER CODE
      }
    JS
  end

  def write_action(root, module_name, name, source)
    directory = File.join(root, 'javascriptsource', module_name, 'actions')
    FileUtils.mkdir_p(directory)
    File.write(File.join(directory, "#{name}.js"), source)
    directory
  end

  it 'reads the called actions with their parameters in call order and their JSDoc types' do
    Dir.mktmpdir do |root|
      write_action(root, 'app', 'Mark', action_source('Mark', 'item, amount, note'))
      write_action(root, 'app', 'Broken', '// no exported function')
      write_action(root, 'app', 'Native', action_source('Native', imports: 'import { Alert } from "react-native";'))
      directory = write_action(root, 'app', 'Parse',
                               action_source('Parse', imports: "import parse from 'url-parse';"))
      expect(described_class.find(root, %w[App.Mark App.Missing App.Broken App.Native App.Parse NoModule]).map(&:name))
        .to eq(['App.Mark'])
      FileUtils.mkdir_p(File.join(directory, 'node_modules', 'url-parse'))
      write_action(root, 'app', 'Scoped', action_source('Scoped', imports: "import x from '@scope/pkg/sub';"))
      FileUtils.mkdir_p(File.join(directory, 'node_modules', '@scope', 'pkg'))

      actions = described_class.find(root, %w[App.Mark App.Parse App.Scoped])
      expect(actions.map(&:name)).to eq(%w[App.Mark App.Parse App.Scoped])
      expect(actions.first).to have_attributes(
        function: 'Mark', packages: [],
        parameters: [{ name: 'item', type: 'MxObject' }, { name: 'amount', type: 'Big' }, { name: 'note', type: '' }]
      )
      expect(actions.map(&:packages)).to eq([[], ['url-parse'], ['@scope/pkg/sub']])
    end
  end

  it 'runs the called actions without a verified adapter from their own source' do
    Dir.mktmpdir do |root|
      app = write_action(root, 'app', 'Mark', action_source('Mark', 'item'))
      File.write(File.join(app, 'helper.js'), 'export const helper = 1;')
      FileUtils.mkdir_p(File.join(app, 'node_modules', 'unused'))
      File.write(File.join(app, 'node_modules', 'unused', 'index.js'), '')
      links = write_action(root, 'links', 'Open', action_source('Open', imports: "import parse from 'url-parse';"))
      FileUtils.mkdir_p(File.join(links, 'node_modules', 'url-parse'))
      File.write(File.join(links, 'node_modules', 'url-parse', 'index.js'), 'export default {};')
      source = '// verified commons fixture'
      stub_const('Mxrb::RubyApp::KnownJavaScriptActions::COMMONS_SOURCES',
                 'GetPlatform' => Digest::SHA256.hexdigest(source))
      write_action(root, 'nanoflowcommons', 'GetPlatform', source)
      project = File.join(root, 'App.mpr')
      Mxrb.define(project) do
        self.module :App do
          entity(:Item) { string :Name }
          javascript_action 'Mark', parameters: [], return_type: { kind: :boolean }, platform: :Web
          nanoflow :Run do
            call_javascript 'App.Mark', as: :marked
            call_javascript 'Links.Open'
            call_javascript 'NanoflowCommons.GetPlatform', as: :platform
          end
        end
      end
      target = File.join(root, 'ruby')
      Mxrb::Exporter.new(project, target, mode: :ruby).export!
      frontend = File.join(target, 'frontend')
      generated = File.read(File.join(frontend, 'src', 'generated', 'nanoflows.ts'))
      vendor = File.join(frontend, 'src', 'generated', 'bridge', 'vendor', 'javascriptsource')

      expect(generated).to include(
        "import { projectJavaScriptActions } from './bridge/projectJavaScriptActions';",
        '...projectJavaScriptActions(import.meta.glob(["./bridge/vendor/javascriptsource/app/actions/Mark.js",' \
        '"./bridge/vendor/javascriptsource/links/actions/Open.js"]), "./bridge/vendor/javascriptsource/", ' \
        '{"App.Mark":{"path":"app/actions/Mark.js","function":"Mark","parameters":[{"name":"item","type":"MxObject"}]}',
        '...nanoflowCommonsActions(["GetPlatform"])'
      )
      expect(generated.index('...projectJavaScriptActions')).to be < generated.index('...feedbackStorageActions')
      expect(File.read(File.join(vendor, 'app', 'actions', 'helper.js'))).to eq('export const helper = 1;')
      expect(File.exist?(File.join(vendor, 'app', 'actions', 'node_modules'))).to be(false)
      expect(File.exist?(File.join(vendor, 'links', 'actions', 'node_modules', 'url-parse', 'index.js'))).to be(true)
      expect(File.exist?(File.join(vendor, 'nanoflowcommons'))).to be(false)
      expect(File.read(File.join(frontend, 'vite.config.ts'))).to include("find: 'mx-global'", 'nativeUnavailable.ts')
    end
  end

  it 'leaves the registration unchanged when no project action runs' do
    Dir.mktmpdir do |root|
      project = File.join(root, 'App.mpr')
      Mxrb.define(project) { self.module(:App) { entity(:Item) { string :Name } } }
      target = File.join(root, 'ruby')
      Mxrb::Exporter.new(project, target, mode: :ruby).export!
      generated = File.read(File.join(target, 'frontend', 'src', 'generated', 'nanoflows.ts'))
      expect(generated).not_to include('projectJavaScriptActions')
    end
  end
end
# rubocop:enable Metrics/BlockLength
